export function loadPage(e){const o=document.getElementById("app");switch(o.innerHTML='<div class="loading">Loading...</div>',e){case"home":window.location.href="./home/home.html";break;case"login":window.location.href="./login/login.html";break;case"signup":window.location.href="./signup/signup.html";break;case"pet-details":const e=new URLSearchParams(window.location.search).get("id");window.location.href=e?"./pets/pet-details.html?id="+e:"./pets/pets.html";break;default:o.innerHTML="<h1>Page Not Found</h1><p>The requested page does not exist.</p>"}}